-- exist until the token is verified), so like `users` it has no tenant_id and no RLS.
CREATE TABLE "signups" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"email" "citext" NOT NULL,
	"org_name" text NOT NULL,
	"desired_slug" text,
	"token_hash" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "signups_token_hash_key" UNIQUE("token_hash"),
	CONSTRAINT "signups_status_check" CHECK ("signups"."status" IN ('pending', 'verified', 'expired', 'cancelled')),
	CONSTRAINT "signups_token_hash_check" CHECK ("signups"."token_hash" ~ '^[0-9a-f]{64}$')
);
